import{X as e,Z as t,t as n,ut as r}from"./chunks/framework.Cq50P25D.js";var i=JSON.parse(`{"title":"Module Management UI","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/module-management-panel.md","filePath":"en/deep-dive/module-management-panel.md","lastUpdated":1785588746000}`),a={name:`deep-dive/module-management-panel.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="module-management-ui" tabindex="-1">Module Management UI <a class="header-anchor" href="#module-management-ui" aria-label="Permalink to “Module Management UI”">​</a></h1><p>Sync engine allows users to load custom modules from custom sources, so it needs an UI to allow users to configure modules.</p><h2 id="ui-composition-and-functions" tabindex="-1">UI Composition and Functions <a class="header-anchor" href="#ui-composition-and-functions" aria-label="Permalink to “UI Composition and Functions”">​</a></h2><p>Modal is a singleton module class accepting context in constructor, extending <code>Modal</code> class, with <code>open()</code> and <code>close()</code> injected into root context.</p><p>Modal frame uses Obsidian CSS variables for large modal:</p><div class="language-css"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">width: var(--modal-width);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">height: var(--modal-height);</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">max-width</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: var(--modal-max-width);</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">max-height</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: var(--modal-max-height);</span></span></code></pre></div><p>Modal has two parts from up to down:</p><ul><li>Native Obsidian controls</li><li>Solid reactive list</li></ul><h3 id="native-obsidian-controls" tabindex="-1">Native Obsidian Controls <a class="header-anchor" href="#native-obsidian-controls" aria-label="Permalink to “Native Obsidian Controls”">​</a></h3><p>A wide search bar at very top, with a small menu icon at right. The bar and the icon take full width of the modal.</p><p>The search bar uses Obsidian API <code>SearchComponent</code>, the menu icon uses Obsidian <code>setIcon</code> + <code>setTooltip</code>, clicking on it opens Obsidian <code>Menu</code>.</p><p>The menu contains only two items: <code>Show installed only</code>, and <code>Edit sources</code>.</p><p>Clicking <code>Show installed only</code> toggles the flag, and becomes checked via <code>MenuItem.setChecked()</code>. Clicking <code>Edit sources</code> opens a new normal modal similar to <code>packages/plugin/src/components/FilterEditorModal.ts</code> that allows user to add and delete module sources.</p><h3 id="solid-reactive-list" tabindex="-1">Solid Reactive List <a class="header-anchor" href="#solid-reactive-list" aria-label="Permalink to “Solid Reactive List”">​</a></h3><p>A solid reactive island also accepts <code>context</code>, majorly consumes <code>Extensibility</code> module APIs. Parent Module Management UI passes three SynthKernel hooks <code>onQuery</code>, <code>onShowInstalledOnlyChange</code>, and <code>onSourcesChange</code> during the reactive list instantiation.</p><p><code>onQuery</code> is fired each keystroke in the search bar carrying the user query. <code>onShowInstalledOnlyChange</code> fired each <code>Show installed only</code> toggle. <code>onSourcesChange</code> is fired each source edit save.</p><p>Once mounted, the reactive list uses <code>fetchSources()</code> to obtain modules list. Then it renders modules as cards. The widths of cards and number of cards per row are adaptive according to current modal width. And cards in each row takes full width of that row. The height of each row depends on the tallest card.</p><p>Each card has the following layout:</p><ul><li>Top row: module name</li><li>Middle block: module description</li><li>Bottom row: right-aligned action buttons</li></ul><p>Action buttons use Obsidian <code>setIcon()</code> and <code>setTooltip()</code>, buttons have following combinations:</p><ul><li>Download button: module not installed, or module has a new version. Clicking on the button triggers <code>downloadModule()</code>.</li><li>Delete button: module installed. Clicking on it triggers <code>deleteModule()</code>.</li><li>Enable button: module installed but not loaded. Clicking on triggers <code>enableModule()</code>.</li><li>Disable button: module installed and loaded. Clicking on triggers <code>disableModule()</code>.</li></ul><p>The modules are sorted alphabetically by default, or sorted in match score if last <code>onQuery</code> payload is non-empty string. Query matching uses Obsidian API <code>prepareFuzzySearch()</code>. Currently, since the module set is small, so no optimization needed.</p><p>When <code>Show installed only</code> is selected, the list should only present installed modules.</p><p>When <code>onSourcesChange</code> fires, the list <code>fetchSources()</code> again and updates.</p>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};